function peopleCameraRig(age,f){const cam=motionEase(age/f.parallaxTime,f.cameraEase),dolly=motionEase((age-f.dollyStart)/f.dollyTime,'smooth'),atStart=motionEase(f.dollyStart/f.parallaxTime,f.cameraEase),exit=motionEase((age-f.dollyStart-f.dollyTime)/3,'smooth');return {cam,dolly,backScale:Math.max(1.08+dolly*.08,(1.08+Math.min(cam,atStart)*f.depth/100*3)*(1-dolly*f.dollyBack/100)),backY:dolly*20,personScale:1+(f.cameraZoom-1)*cam+dolly*f.dollyFront/100,rise:cam*330*f.cameraRise/100+dolly*f.dollyDrop+exit*220}}
function formatClipTime(n){n=Math.round(n);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0')}
/* Layered camera continuation and directly manipulable fire layers. */
const epiCanvases={};for(const key of ['sky','back','portraits','final','pull']){const c=document.createElement('canvas');c.width=960;c.height=540;epiCanvases[key]=c}
function saveEffects(){localStorage.setItem('motion-effects',JSON.stringify(fx));base._renderKey=''}
function cloudBand(ctx,x,y,w,h,alpha=1){if(!ready(sprites.clouds))return;ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(sprites.clouds,x,y,w,h);ctx.restore()}
function heritageLogo(ctx,side,x,y,size,alpha){ctx.save();ctx.translate(x,y);ctx.scale(size,size);ctx.globalAlpha=alpha;ctx.fillStyle='#17212b';ctx.strokeStyle='#17212b';ctx.lineWidth=2;ctx.textAlign='center';if(side===0){ctx.font='600 13px Arial';ctx.fillText('ADOLF DASSLER',0,-57);ctx.save();ctx.rotate(-.17);ctx.beginPath();ctx.moveTo(-35,-17);ctx.bezierCurveTo(-25,-35,-20,-38,-12,-25);ctx.lineTo(0,-10);ctx.lineTo(27,-5);ctx.quadraticCurveTo(44,4,30,12);ctx.lineTo(-32,12);ctx.quadraticCurveTo(-45,4,-35,-17);ctx.stroke();for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-16+i*8,-20);ctx.lineTo(-25+i*8,3);ctx.stroke()}ctx.restore();ctx.font='bold 37px Arial';ctx.fillText('adidas',0,47);ctx.font='bold 9px Arial';ctx.fillText('SPORTSCHUHE',0,62)}else{ctx.beginPath();for(let i=0;i<6;i++){const a=Math.PI/3*i;const x=Math.cos(a)*70,y=Math.sin(a)*70;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.stroke();ctx.font='bold 39px Georgia';ctx.fillText('P',0,-7);ctx.beginPath();ctx.moveTo(-28,0);ctx.quadraticCurveTo(2,-17,31,-4);ctx.lineTo(14,4);ctx.lineTo(-7,2);ctx.lineTo(-24,10);ctx.fill();ctx.font='bold 27px Georgia';ctx.fillText('PUMA',0,32);ctx.font='bold 8px Arial';ctx.fillText('SCHUHFABRIK',0,49)}ctx.restore()}
function movingSky(ctx,secs,d,boundary){const s=epiCanvases.sky,c=s.getContext('2d');c.clearRect(0,0,960,540);c.fillStyle='#6197cb';c.fillRect(0,0,960,540);const drift=((secs-d.outdoor)*fx.cloudSpeed*1.3)%1200;cloudBand(c,-drift,-75,1200,460);cloudBand(c,1200-drift,-75,1200,460);cloudBand(c,500-drift*.55,180,1000,360,.65);if(boundary<960){c.save();c.beginPath();c.rect(boundary,0,960-boundary,540);c.clip();c.globalCompositeOperation='color';c.fillStyle=fx.redColor;c.fillRect(boundary,0,960-boundary,540);c.globalCompositeOperation='source-over';c.globalAlpha=.28;c.fillRect(boundary,0,960-boundary,540);c.restore()}c.globalCompositeOperation='destination-in';c.drawImage(roofMask,0,0);c.globalCompositeOperation='source-over';ctx.drawImage(s,0,0)}
function renderEpilogue(ctx,secs,d){if(secs>=d.blue-.001){ctx.fillStyle=fx.endBlue;ctx.fillRect(0,0,960,540);return}const age=secs-d.parallax,{cam,dolly,backScale,backY,personScale,rise}=peopleCameraRig(age,fx);
const bg=epiCanvases.back,b=bg.getContext('2d');b.clearRect(0,0,960,540);landscapePlate(b);composeRoofPortraits(b);const redProgress=ease((secs-d.red)/fx.redSpeed),boundary=960-480*redProgress;movingSky(b,secs,d,boundary);
// Giant cutouts remain occluded by the roof silhouette; they move at a different depth.
const portraits=epiCanvases.portraits,p=portraits.getContext('2d');p.clearRect(0,0,960,540);p.save();p.globalAlpha=.9;const ps=1+cam*fx.portraitDepth/100;drawBackPiece(p,0,180-200*ps,-100-80*cam,400*ps,420*ps);drawBackPiece(p,1,800-215*ps,-95-80*cam,430*ps,430*ps);p.restore();p.globalCompositeOperation='destination-in';p.drawImage(roofMask,0,0);p.globalCompositeOperation='source-over';b.drawImage(portraits,0,0);
const logos=ease((secs-d.logos)/fx.logoFade);heritageLogo(b,0,345,90,1+cam*.22,logos*.9);heritageLogo(b,1,645,90,1+cam*.22,logos*.9);if(redProgress>0){const sky=epiCanvases.sky,sc=sky.getContext('2d');sc.clearRect(0,0,960,540);cloudBand(sc,boundary-105,385+Math.sin(age*.4)*5,220,130,.92);sc.globalCompositeOperation='destination-in';sc.drawImage(roofMask,0,0);sc.globalCompositeOperation='source-over';b.drawImage(sky,0,0)}if(fx.blurMode==='background')applyRegionBlur(b,'all',fx.blur);
const frame=epiCanvases.final,c=frame.getContext('2d');c.clearRect(0,0,960,540);c.fillStyle='#648eb9';c.fillRect(0,0,960,540);c.save();c.translate(480,245+backY);c.scale(backScale,backScale);c.translate(-480,-245);c.drawImage(bg,0,0);c.restore();c.save();c.translate(480,75+rise);c.scale(personScale,personScale);c.translate(-480,-75);drawStandingPiece(c,0,348,56,158,435,1);drawStandingPiece(c,1,496,65,158,435,1);c.restore();if(fx.blurMode==='edges'||fx.blurMode==='custom')applyRegionBlur(c,fx.blurMode,fx.blur);
const pull=clamp((secs-d.warp)/fx.warpTime);if(pull<=0){ctx.drawImage(frame,0,0);return}ctx.fillStyle=fx.endBlue;ctx.fillRect(0,0,960,540);const power=fx.warpPower/100,k=1+ease(pull)*power*.8;ctx.save();ctx.globalAlpha=1-motionEase(pull,'smooth');ctx.filter=`blur(${pull*power*30}px)`;ctx.translate(480,270);ctx.scale(k,k);ctx.drawImage(frame,-480,-270);ctx.restore();if(pull>.88){ctx.fillStyle=fx.endBlue;ctx.fillRect(0,0,960,540)}}
const outdoorBeforeCamera=renderOutdoor;renderOutdoor=function(ctx,secs,d){if(secs>=d.parallax&&ready(sprites.clouds))renderEpilogue(ctx,secs,d);else outdoorBeforeCamera(ctx,secs,d)};
const photoBeforeLayers=photographedFire;photographedFire=function(ctx,secs,strength,video){const ok=photoBeforeLayers(ctx,secs,strength,video);if(!ok)return false;for(const [i,l] of fx.extraFires.entries()){if(l.visible===false)continue;const w=430*l.size,h=245*l.size;ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=strength*l.opacity;ctx.translate(l.x,l.y);ctx.rotate((l.rotation||0)*Math.PI/180);ctx.filter=`hue-rotate(${hueShift(fx.fireColor)}deg) saturate(1.2)`;const iw=video.videoWidth,ih=video.videoHeight;const sx=.13*iw;ctx.drawImage(video,sx,ih*.12,iw*.78,ih*.665,-w/2,-h,w,h);ctx.restore()}return true};
let selectedFire=-1,fireDrag=null;const fireHandles=document.createElement('div');fireHandles.className='fireHandles';base.append(fireHandles);
function cameraTransform(){const d=phaseTimes(),secs=t*settings.duration,F=1+(fx.peopleZoom-1)*ease((secs-d.people)/fx.peopleZoomTime),S=.7+(fx.sceneZoom-.7)*ease((secs-d.lamp)/8);return{scale:F*S,x:540+F*(480-540)-F*S*480,y:220+F*(330-220)-F*S*330}}
function localToPreview(x,y){const m=cameraTransform();return{x:x*m.scale+m.x,y:y*m.scale+m.y}}
function previewToLocal(e){const r=base.getBoundingClientRect(),m=cameraTransform();return{x:((e.clientX-r.left)/r.width*960-m.x)/m.scale,y:((e.clientY-r.top)/r.height*540-m.y)/m.scale}}
function updateFireHandles(){const phase=phaseTimes(),now=t*settings.duration;fireHandles.style.display=activeEffect==='fire'&&now>=phase.fire&&now<phase.outdoor?'block':'none';if(activeEffect!=='fire')return;const layers=[{x:480+fx.baseFireX,y:350+fx.baseFireY},...fx.extraFires];if(fireHandles.childElementCount!==layers.length){fireHandles.innerHTML='';layers.forEach((l,i)=>{const button=document.createElement('button');button.className='fireHandle';button.textContent='✥';button.setAttribute('aria-label',i?'Move fire layer '+i:'Move main fire');button.onpointerdown=e=>{e.preventDefault();e.stopPropagation();selectedFire=i-1;const point=previewToLocal(e);fireDrag={index:i-1,start:point,x:i?fx.extraFires[i-1].x:fx.baseFireX,y:i?fx.extraFires[i-1].y:fx.baseFireY};playing=false;button.setPointerCapture(e.pointerId);showFireSelection()};button.onpointermove=e=>{if(!fireDrag)return;const p=previewToLocal(e),dx=p.x-fireDrag.start.x,dy=p.y-fireDrag.start.y;if(fireDrag.index<0){fx.baseFireX=fireDrag.x+dx;fx.baseFireY=fireDrag.y+dy}else{const layer=fx.extraFires[fireDrag.index];layer.x=fireDrag.x+dx;layer.y=fireDrag.y+dy}saveEffects()};button.onpointerup=e=>{fireDrag=null;e.stopPropagation();saveEffects()};button.onclick=e=>{e.stopPropagation();selectedFire=i-1;showFireSelection()};fireHandles.append(button)})}layers.forEach((l,i)=>{const pos=localToPreview(l.x,l.y),button=fireHandles.children[i];button.style.left=pos.x/960*100+'%';button.style.top=pos.y/540*100+'%';button.classList.toggle('selected',selectedFire===i-1)})}
function showFireSelection(){const block=document.querySelector('#fireLayerControls');if(!block)return;block.innerHTML=`<p class="sub">${selectedFire<0?'Main fire selected. Drag its handle in the preview.':'Fire layer '+(selectedFire+1)+' selected. Drag its handle in the preview.'}</p>${selectedFire>=0?'<label for="layerSize">Layer size</label><input id="layerSize" type="range" min=".3" max="2.5" step=".05"><label for="layerOpacity">Layer strength</label><input id="layerOpacity" type="range" min="0" max="1" step=".05"><button class="pill" id="removeLayer" style="margin-top:12px;width:100%">Remove this layer</button>':''}`;if(selectedFire>=0){const l=fx.extraFires[selectedFire],size=block.querySelector('#layerSize'),opacity=block.querySelector('#layerOpacity');size.value=l.size;opacity.value=l.opacity;size.oninput=()=>{l.size=+size.value;saveEffects()};opacity.oninput=()=>{l.opacity=+opacity.value;saveEffects()};block.querySelector('#removeLayer').onclick=()=>{fx.extraFires.splice(selectedFire,1);selectedFire=-1;saveEffects();showFireSelection()}}updateFireHandles()}
const selectBeforeLayers=selectEffect;selectEffect=function(key,jump=true){selectBeforeLayers(key,jump);if(key==='fire'){const block=document.createElement('div');block.className='fireLayersPanel';block.innerHTML='<label>Place your fire</label><button class="pill" id="addFireLayer" style="width:100%">+ Add fire layer</button><div id="fireLayerControls"></div>';controls.querySelector('#watchEffect').after(block);block.querySelector('#addFireLayer').onclick=()=>{if(fx.extraFires.length>=8)return;fx.extraFires.push({x:350+fx.extraFires.length*45,y:350,size:1,opacity:.85,rotation:0,visible:true});selectedFire=fx.extraFires.length-1;const d=phaseTimes();t=(d.fire+fx.fireBuild+1)/settings.duration;playing=false;document.querySelector('#play').textContent='▶';saveEffects();showFireSelection()};showFireSelection()}if(key==='light'){controls.querySelector('#swapEffect').onclick=()=>chooseAsset('deskLamp');controls.querySelector('#swapEffect').textContent='Choose desk & lamp photo…';const separate=controls.querySelector('#swapLamp');if(separate)separate.style.display='none'}if(key==='camera'||key==='finish'){const swap=controls.querySelector('#swapEffect');swap.previousElementSibling.style.display='none';swap.style.display='none';if(key==='finish'){const colors=document.createElement('div');colors.innerHTML='<label for="redPanelColor">Red panel color</label><input id="redPanelColor" type="color"><label for="endBlueColor">Final screen color</label><input id="endBlueColor" type="color">';controls.querySelector('#watchEffect').after(colors);for(const [id,k] of [['redPanelColor','redColor'],['endBlueColor','endBlue']]){const input=colors.querySelector('#'+id);input.value=fx[k];input.oninput=()=>{fx[k]=input.value;saveEffects();startPart(key,true)}}}}updateFireHandles()};
const beforeHandlesFrame=frame;frame=function(el,p){beforeHandlesFrame(el,p);if(el===base){updateFireHandles();const d=phaseTimes(),secs=p*settings.duration,key=secs>=d.red?'finish':secs>=d.parallax?'camera':secs>=d.outdoor?'outdoor':secs>=d.people?'people':secs>=d.fire?'fire':secs>=d.lamp?'light':secs>=d.tear?'zoom':'tears';stages.querySelectorAll('button').forEach(b=>b.classList.toggle('playing',b.dataset.stage===key))}};
base.onclick=()=>{const d=phaseTimes(),secs=t*settings.duration,key=secs>=d.red?'finish':secs>=d.parallax?'camera':secs>=d.outdoor?'outdoor':secs<d.tear?'tears':secs<d.lamp?'zoom':secs<d.fire?'light':secs<d.people?'fire':'people';selectEffect(key,false);playing=false;document.querySelector('#play').textContent='▶'};
